<template><label class="vs-check"><input :checked="modelValue" type="checkbox" :disabled="disabled" :aria-describedby="descriptionId" @change="$emit('update:modelValue', $event.target.checked)" /><span class="vs-check__control" aria-hidden="true">✓</span><span><strong>{{ label }}</strong><small v-if="description" :id="descriptionId">{{ description }}</small></span></label></template>
<script setup>import { computed } from 'vue'; const props=defineProps({ id:{type:String,required:true},modelValue:Boolean,label:{type:String,required:true},description:{type:String,default:''},disabled:Boolean }); defineEmits(['update:modelValue']); const descriptionId=computed(()=>props.description?`${props.id}-description`:undefined)</script>
<style scoped>.vs-check{display:inline-flex;align-items:flex-start;gap:var(--space-3);min-height:44px;color:var(--text-primary);cursor:pointer}.vs-check input{position:absolute;opacity:0}.vs-check__control{display:grid;place-items:center;width:22px;height:22px;margin-top:1px;border:1px solid var(--border-strong);border-radius:6px;background:var(--surface-default);color:transparent}.vs-check input:checked+.vs-check__control{background:var(--interactive-primary);border-color:var(--interactive-primary);color:var(--text-on-interactive)}.vs-check input:focus-visible+.vs-check__control{outline:3px solid color-mix(in srgb,var(--border-focus) 35%,transparent);outline-offset:2px}.vs-check strong,.vs-check small{display:block}.vs-check small{color:var(--text-muted);font-size:var(--type-caption-size);line-height:var(--type-caption-line)}</style>
